package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ListPopulation.iterator()
 */
public class ListPopulation_iterator_TriageGen5Test {

    /**
     * Mock implementation of Chromosome to facilitate testing.
     */
    private static class MockChromosome implements Chromosome {
        @Override
        public double getFitness() {
            return 1.0;
        }

        @Override
        public Chromosome copy() {
            return new MockChromosome();
        }
    }

    @Test
    public void testIteratorWithEmptyPopulation() {
        int limit = 10;
        ListPopulation population = new ListPopulation(limit);

        Iterator<Chromosome> iterator = population.iterator();

        Assert.assertNotNull("Iterator should not be null", iterator);
        Assert.assertFalse("Iterator should be empty", iterator.hasNext());
    }

    @Test
    public void testIteratorWithMultipleChromosomes() {
        int limit = 10;
        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        Chromosome c3 = new MockChromosome();
        List<Chromosome> list = Arrays.asList(c1, c2, c3);

        ListPopulation population = new ListPopulation(list, limit);

        Iterator<Chromosome> iterator = population.iterator();

        Assert.assertNotNull("Iterator should not be null", iterator);
        Assert.assertTrue("Iterator should have elements", iterator.hasNext());

        // Verify first element
        Assert.assertSame("First element should match c1", c1, iterator.next());
        Assert.assertTrue("Iterator should have more elements", iterator.hasNext());

        // Verify second element
        Assert.assertSame("Second element should match c2", c2, iterator.next());
        Assert.assertTrue("Iterator should have more elements", iterator.hasNext());

        // Verify third element
        Assert.assertSame("Third element should match c3", c3, iterator.next());
        Assert.assertFalse("Iterator should be empty now", iterator.hasNext());
    }

    @Test
    public void testIteratorAfterAddingChromosomes() {
        int limit = 5;
        ListPopulation population = new ListPopulation(limit);
        Chromosome c1 = new MockChromosome();

        population.addChromosome(c1);

        Iterator<Chromosome> iterator = population.iterator();

        Assert.assertTrue(iterator.hasNext());
        Assert.assertSame(c1, iterator.next());
        Assert.assertFalse(iterator.hasNext());
    }

    @Test
    public void testIteratorAfterSetChromosomes() {
        int limit = 5;
        Chromosome c1 = new MockChromosome();
        Chromosome c2 = new MockChromosome();
        ListPopulation population = new ListPopulation(limit);

        population.setChromosomes(Arrays.asList(c1, c2));

        Iterator<Chromosome> iterator = population.iterator();

        int count = 0;
        while (iterator.hasNext()) {
            iterator.next();
            count++;
        }

        Assert.assertEquals("Iterator should return exactly 2 elements after setChromosomes", 2, count);
    }
}
